<div class="row"><div class="field"><label>DIČ</label><input name="dic" value="<?=\App\Core\View::e($customer['dic']??'')?>"></div><div class="field"><label>E-mail</label><input type="email" name="email" value="<?=\App\Core\View::e($customer['email']??'')?>"></div></div>
