<div class="card customer-address-card"><h3>Fakturační adresa</h3><p class="sub">Adresa zákazníka používaná na fakturách a dalších dokladech.</p><div class="row"><div class="field"><label>Ulice</label><input name="street" value="<?=\App\Core\View::e($customer['street']??'')?>"></div><div class="field"><label>Město</label><input name="city" value="<?=\App\Core\View::e($customer['city']??'')?>"></div></div><div class="field"><label>PSČ</label><input name="zip" value="<?=\App\Core\View::e($customer['zip']??'')?>" inputmode="numeric" autocomplete="postal-code"></div></div>
<div class="card customer-address-card"><h3>Dodací adresa</h3><p class="sub">Pokud je stejná jako fakturační, nic dalšího nastavovat nemusíte.</p><label class="switch customer-delivery-toggle"><input type="checkbox" id="deliveryDifferent" name="delivery_different" value="1" <?=!$deliverySame?'checked':''?>><span class="track"></span><span>Dodací adresa je jiná než fakturační</span></label><div id="deliveryFields" class="delivery-fields" style="display:<?=!$deliverySame?'block':'none'?>"><div class="row"><div class="field"><label>Ulice</label><input name="delivery_street" value="<?=\App\Core\View::e($customer['delivery_street']??'')?>"></div><div class="field"><label>Město</label><input name="delivery_city" value="<?=\App\Core\View::e($customer['delivery_city']??'')?>"></div></div><div class="field"><label>PSČ</label><input name="delivery_zip" value="<?=\App\Core\View::e($customer['delivery_zip']??'')?>" inputmode="numeric" autocomplete="postal-code"></div></div></div>
