</form>
<script>
(function(){const c=document.getElementById('deliveryDifferent'),f=document.getElementById('deliveryFields');if(!c||!f)return;function sync(){f.style.display=c.checked?'block':'none';if(!c.checked)f.querySelectorAll('input').forEach(i=>i.value='')}c.addEventListener('change',sync)})();
</script>
